(function(){
  window.wp = window.wp || {};
  if (!window.wp.hooks) {
    var actions = {};
    var filters = {};
    window.wp.hooks = {
      addAction: function(name, ns, fn, priority) {
        actions[name] = actions[name] || [];
        actions[name].push({ ns: ns, fn: fn, priority: priority || 10 });
      },
      addFilter: function(name, ns, fn, priority) {
        filters[name] = filters[name] || [];
        filters[name].push({ ns: ns, fn: fn, priority: priority || 10 });
      },
      removeAction: function(name, ns) {
        if (actions[name]) actions[name] = actions[name].filter(function(h) { return h.ns !== ns; });
      },
      removeFilter: function(name, ns) {
        if (filters[name]) filters[name] = filters[name].filter(function(h) { return h.ns !== ns; });
      },
      doAction: function(name) {
        var args = Array.prototype.slice.call(arguments, 1);
        var list = actions[name] || [];
        list.slice().sort(function(a, b) { return a.priority - b.priority; }).forEach(function(h) {
          try { h.fn.apply(null, args); } catch (e) { console.warn(e); }
        });
      },
      applyFilters: function(name, value) {
        var args = Array.prototype.slice.call(arguments, 1);
        var list = filters[name] || [];
        list.slice().sort(function(a, b) { return a.priority - b.priority; }).forEach(function(h) {
          try { value = h.fn.apply(null, args); args[0] = value; } catch (e) { console.warn(e); }
        });
        return value;
      },
      hasAction: function(name, ns) { return !!(actions[name] && (!ns || actions[name].some(function(h){ return h.ns === ns; }))); },
      hasFilter: function(name, ns) { return !!(filters[name] && (!ns || filters[name].some(function(h){ return h.ns === ns; }))); }
    };
  }
})();